    h+=(live?'<div class="m" style="margin-top:10px">This program is live. Changes save as you make them and show in the client\'s app.</div>':"")+'</div>';
    var q=st.q.toLowerCase(), R=DB.EX.filter(function(x){return x.status!=="Archived"&&(!q||x.name.toLowerCase().indexOf(q)>=0)&&(st.cat==="All"||(st.cat==="Recent"?st.recent.indexOf(x.name)>=0:x.cat===st.cat))});
    h+='<aside class="wb-side"><div class="k">'+(st.swap?"Pick the replacement":"Add exercises")+'</div><input class="search" id="wbq" type="search" placeholder="Search exercises" aria-label="Search exercises" value="'+esc(st.q)+'" style="max-width:none;width:100%;margin-top:6px"><div class="pills" style="margin-top:8px">'+["All","Recent","Lower","Upper","Core","Conditioning"].map(function(c){return '<button data-act="wcat" data-id="'+c+'" aria-pressed="'+(st.cat===c)+'">'+c+'</button>'}).join("")+'</div><div class="wb-res" id="wbres">'+resHTML(R)+'</div></aside></div></section>';
