  function find(u){var d=day(), r=null; d.items.forEach(function(it,i){ if(it.uid===u) r={list:d.items,i:i,e:it}; if(it.g) it.items.forEach(function(x,j){ if(x.uid===u) r={list:it.items,i:j,e:x,g:it} })}); return r}
